Write-Host "current==hcai: $($key -eq $hcai)"

function Test-Key($name, $k) {
  try {
    $headers = @{ Authorization = "Bearer $k"; "Content-Type"="application/json" }
    # lightweight probe: models list often works on one-api
    $r = Invoke-WebRequest -Uri "https://ai.hctopup.com/v1/models" -Headers $headers -Method GET -TimeoutSec 20
    Write-Host "[$name] models OK status=$($r.StatusCode) body=$($r.Content.Substring(0,[Math]::Min(200,$r.Content.Length)))"
  } catch {
    $resp = $_.Exception.Response
    if ($resp) {
      $reader = New-Object IO.StreamReader($resp.GetResponseStream())
      $body = $reader.ReadToEnd()
      Write-Host "[$name] FAIL status=$([int]$resp.StatusCode) body=$body"
    } else {
      Write-Host "[$name] FAIL err=$($_.Exception.Message)"
    }
  }
}

Test-Key "current-auth" $key
