input.contents:
import sqlite3, json, os, re

db = os.path.expanduser(r"~/.cc-switch/cc-switch.db")
con = sqlite3.connect(db)
cur = con.cursor()
tables = [r[0] for r in cur.execute("SELECT name FROM sqlite_master WHERE type='table'")]
print("tables:", tables)

def mask_text(vs: str) -> str:
    def repl(m):
        k = m.group(0)
        return k[:12] + "...len" + str(len(k))
    return re.sub(r"sk-[A-Za-z0-9_-]{10,}", repl, vs)

for t in tables:
    cols = [r[1] for r in cur.execute(f"PRAGMA table_info({t})")]
    rows = cur.execute(f"SELECT * FROM {t}").fetchall()
    print(f"\n== {t} cols={cols} rows={len(rows)}")
    for row in rows:
        parts = []
        for c, v in zip(cols, row):
            if v is None:
                parts.append(f"{c}=None")
                continue
            vs = str(v)
            low = c.lower()
            interesting = any(x in low for x in ["provider", "name", "id", "url", "base", "active", "current", "app", "type", "key", "auth", "config", "settings"])
            if not interesting and len(vs) < 80:
                parts.append(f"{c}={vs}")
                continue
            if any(x in low for x in ["key", "token", "secret", "password", "auth"]) or "OPENAI_API_KEY" in vs or vs.startswith("sk-"):
                # extract keys
                keys = re.findall(r"sk-[A-Za-z0-9_-]{20,}", vs)
                keyinfo = ",".join(f"{k[:12]}...len{len(k)}" for k in keys[:5])
                parts.append(f"{c}=***len{len(vs)} keys=[{keyinfo}]")
            elif len(vs) > 200:
                parts.append(f"{c}=<{len(vs)} chars> {mask_text(vs[:120])}")
            else:
                parts.append(f"{c}={mask_text(vs)}")
        print(" | ".join(parts))

input.command:
$key = (Get-Content "$env:USERPROFILE\.codex\auth.json" -Raw | ConvertFrom-Json).OPENAI_API_KEY
Write-Host "=== /v1/models ==="
curl.exe -sS --max-time 20 -H "Authorization: Bearer $key" "https://api.tangguo.xin/v1/models"
Write-Host "`n=== probe sol / luna / terra / 5.5 ==="
foreach ($m in @('gpt-5.6-sol','gpt-5.6-luna','gpt-5.6-terra','gpt-5.5')) {
  Set-Content -LiteralPath "$env:TEMP\body.json" -Value "{`"model`":`"$m`",`"input`":`"ping`",`"max_output_tokens`":8}" -Encoding ascii
  curl.exe -sS --max-time 25 -o "$env:TEMP\out_$m.json" -w "${m} http=%{http_code} t=%{time_total}`n" -H "Authorization: Bearer $key" -H "Content-Type: application/json" --data-binary "@$env:TEMP\body.json" "https://api.tangguo.xin/v1/responses"
  if (Test-Path "$env:TEMP\out_$m.json") {
    $b = Get-Content "$env:TEMP\out_$m.json" -Raw
    if ($b.Length -gt 180) { $b = $b.Substring(0,180) }
    Write-Host "  $b"
  }
}
Write-Host "`n=== config model ==="
Select-String -LiteralPath "$env:USERPROFILE\.codex\config.toml" -Pattern '^model '
Write-Host "`n=== catalog sol mentions ==="
if (Test-Path "$env:USERPROFILE\.codex\model-catalogs\ccs-one-api-1782980572222.json") {
  Select-String -LiteralPath "$env:USERPROFILE\.codex\model-catalogs\ccs-one-api-1782980572222.json" -Pattern '5\.6-sol|gpt-5\.6' | Select-Object -First 20
}
